124	                    AnyMdInline::MdTextual(text) => {
125	                        joiner.entry(&text.format().with_options(FormatMdTextualOptions {
126	                            should_remove: true,
127	                            trim_start: true,
128	                            ..Default::default()
129	                        }));
130	                    }
