132	                        joiner.entry(&hard_line.format().with_options(
133	                            FormatMdFormatHardLineOptions {
134	                                print_mode: TextPrintMode::Trim(TrimMode::All),
135	                            },
136	                        ));
137	                    }
138	                    _ => {
139	                        joiner.entry(&item.format());
