/// Returns `true` when `node` is the last hard line break of its paragraph
/// block, meaning no content line follows it in the same block.
///
/// This is the case when the hard line break has no following sibling, or when
/// its immediate following sibling is empty text (whitespace or a newline),
/// which signals that a blank line — not another content line — comes next.
fn is_last_hard_line(node: &MdHardLine) -> bool {
    match node.syntax().next_sibling() {
        // No sibling at all: this is the last item of the block.
        None => true,
        // An empty textual sibling (blank line / trailing newline) means no
        // content line follows in the same paragraph.
        Some(next) => MdTextual::cast(next).is_some_and(|text| text.is_empty().unwrap_or(false)),
    }
